position: absolute;
top: 0;
right: 0;
bottom: 0;
left: 0;
z-index: 1;
}

& .has-child {
gap: var(--wp--preset--spacing--extra-small);
}

&:is(.is-responsive) .wp-block-navigation-item > a {
