align-items: center;
box-sizing:border-box;
padding: var(--wp--preset--spacing--small) 12px !important;
min-height: 48px;
border-radius: 12px !important;
color: var(--wp--preset--color--on-tertiary-container) !important;
background-color: var(--wp--preset--color--tertiary-container) !important;
}

&:not(.is-responsive) .wp-block-navigation-item.current-menu-item > a {
color: var(--wp--preset--color--tertiary) !important;
text-decoration: var(--wp--preset--color--tertiary) 2px underline;
text-underline-offset: var(--wp--preset--spacing--small) !important;
}

&:not(.is-responsive) .wp-block-navigation-item.current-menu-ancestor > a {
color: var(--wp--preset--color--tertiary) !important;
text-decoration: var(--wp--preset--color--tertiary) 2px underline !important;
