}

& .wp-block-navigation__submenu-container .wp-block-navigation-item:active{
color: var(--wp--preset--color--on-tertiary-container) !important;
background-color: var(--wp--preset--color--tertiary-container) !important;
}

& .wp-block-navigation__submenu-container .wp-block-navigation-item.current-menu-item {
